            ["min_fps"] = new[] {
                "FPS limit for the world spawn",
                "Лимит на FPS за световното създаване",
                "全图生成的帧率下限",
                "全圖生成的影格率下限",
                "Limit FPS pro zaplnění světa",
                "FPS-grænse for verdensoprettelsen",
                "FPS-grens voor het vullen van de wereld",
                "FPS-raja maailman täytölle",
                "Limite de FPS pour le remplissage du monde",
                "FPS-Grenze für den Weltspawn",
                "विश्व स्पॉन के लिए FPS सीमा",
                "FPS-határ a világ feltöltéséhez",
                "Limite FPS per il riempimento del mondo",
                "ワールド生成の FPS 下限",
                "월드 생성 FPS 하한",
                "FPS-grense for verdensoppretting",
                "Limit FPS dla zapełniania świata",
                "Limite de FPS para o preenchimento do mundo",
                "Limite de FPS para o preenchimento do mundo",
                "Limită FPS pentru popularea lumii",
                "Предел FPS для заполнения мира",
                "Limit FPS pre zaplnenie sveta",
                "Límite de FPS para el llenado del mundo",
